import{_ as a,c as r,o as e,a0 as i}from"./chunks/framework.C1J0Vcxi.js";const _=JSON.parse('{"title":"第三十三周：K3 GMAC 网卡驱动调通 + AMP IPC 真板闭环","description":"","frontmatter":{},"headers":[],"relativePath":"周报-Oveln/2026-08-14-周报三十三.md","filePath":"周报-Oveln/2026-08-14-周报三十三.md"}'),s={name:"周报-Oveln/2026-08-14-周报三十三.md"};function o(l,t,d,n,c,h){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="第三十三周-k3-gmac-网卡驱动调通-amp-ipc-真板闭环" tabindex="-1">第三十三周：K3 GMAC 网卡驱动调通 + AMP IPC 真板闭环 <a class="header-anchor" href="#第三十三周-k3-gmac-网卡驱动调通-amp-ipc-真板闭环" aria-label="Permalink to &quot;第三十三周：K3 GMAC 网卡驱动调通 + AMP IPC 真板闭环&quot;">​</a></h1><h2 id="一、本周完成" tabindex="-1">一、本周完成 <a class="header-anchor" href="#一、本周完成" aria-label="Permalink to &quot;一、本周完成&quot;">​</a></h2><p><strong>驱动</strong></p><ul><li><strong>GMAC 网卡</strong>（DWMAC 5.10a + RTL8211F，tgoskits feat/k3-gmac-net）：修复三个 寄存器定义错误（TSF 位、DMA 软复位缺失、MTL 通道基址）后 DHCP / ping 通过。 排查复盘见技术报告《K3 GMAC 网卡驱动调试教训》</li><li><strong>rt_shm</strong>（AP 侧 /dev/rt_shm）：定案 X100 上 PBMT 不生效——改为四处 CBO 缓存同步点；mailbox ack 改 FIFO 排空循环；AWAIT 锁内重查前二次作废</li><li><strong>IMSIC</strong>（tgoskits）：stopei claim+complete 合并为单条 csrrw（对齐 Linux）， 修复读写分离窗口吞 MSI</li></ul><p><strong>部件 / 推进</strong></p><ul><li>共享内存窗口定案：SRAM 起始 0xc0800000 / 0x19000（amp.toml 与两侧 dts 对齐）；补启动期防护——3s 写入门控（SPL 执行区 + U-Boot 清窗）+ magic 自愈看门狗；QEMU 窗口同步扩到 0x19000</li><li><strong>AMP IPC 推进到真板闭环</strong>：user-test-ipc 三轮 RPC（通知回显 + ADD 断言） 100% 通过。挂死根因为 ov-rpc NOTIFY_FLAG 缺失（Quiet 回包无门铃），三层 排查过程见技术报告《一次 AMP IPC 挂死的三层排查》</li><li>tgoskits 分支栈重构（riscv-aia ← k3-board-support ← rt-async-amp）并 force-push；三仓收束提交（调试期无效修改全撤 + subagent 审阅）</li></ul><h2 id="二、待办" tabindex="-1">二、待办 <a class="header-anchor" href="#二、待办" aria-label="Permalink to &quot;二、待办&quot;">​</a></h2><ul><li>tgoskits 走双仓合并流程（先子后主）回集成分支</li><li>menvcfg.PBMTE 调研：修通后可省逐操作 CBO 开销</li><li>RP boot #1 偶发静默死亡观察</li></ul><h2 id="三、本周技术报告" tabindex="-1">三、本周技术报告 <a class="header-anchor" href="#三、本周技术报告" aria-label="Permalink to &quot;三、本周技术报告&quot;">​</a></h2><ul><li><a href="./../技术报告/2026-08-14-K3-GMAC驱动调试教训.html">K3 GMAC 网卡驱动调试教训</a>： 三个寄存器定义错误的定位过程与弯路复盘</li><li><a href="./../技术报告/2026-08-16-AMP-IPC挂死三层排查.html">一次 AMP IPC 挂死的三层排查</a>： 缓存属性（PBMT 不生效）/ 中断原子性（stopei csrrw）/ 协议标志位 （NOTIFY_FLAG）三层根因与 wget 掩蔽效应</li></ul><h2 id="四、提交位置" tabindex="-1">四、提交位置 <a class="header-anchor" href="#四、提交位置" aria-label="Permalink to &quot;四、提交位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>仓库</th><th>位置</th><th>内容</th></tr></thead><tbody><tr><td>tgoskits</td><td>feat/riscv-aia</td><td>IMSIC csrrw 修复</td></tr><tr><td>tgoskits</td><td>feat/rt-async-amp</td><td>rt_shm 修复 + 共享窗收回 0x19000</td></tr><tr><td>rt-async-amp</td><td>master</td><td>窗口落位 + 启动期防护 + NOTIFY_FLAG 修复 + QEMU 窗口</td></tr><tr><td>tgoskits-k3-gmac</td><td>feat/k3-gmac-net</td><td>GMAC 驱动（诊断代码待清理）</td></tr></tbody></table>',12)])])}const p=a(s,[["render",o]]);export{_ as __pageData,p as default};
